// Название без повторов: «Дизайнер», «Дизайнер 2»
function uniqueName(name, list) {
  const taken = new Set(list.map((r) => r.name.toLowerCase()));
  let candidate = name;
  for (let n = 2; taken.has(candidate.toLowerCase()); n++) candidate = `${name} ${n}`;
  return candidate;
}
